<script setup>
import{computed,reactive,ref}from'vue';import QuizCard from'./QuizCard.vue';import YesNoCard from'./YesNoCard.vue';import FreeTextCard from'./FreeTextCard.vue';import{createMistakeRound,loadMistakeSession,mistakeSummary,openMistakes,recordMistake,saveMistakeSession}from'../utils/mistakeStore.js'
const props=defineProps({packageBanksById:{type:Object,required:true}});const setup=ref(true),s=reactive({orderedQuestionRefs:[],currentQuestionIndex:0,answers:{},sessionStatus:'inProgress'}),selected=ref(null),answered=ref(false);const summary=computed(()=>mistakeSummary());const lookup=computed(()=>new Map(Object.values(props.packageBanksById).flatMap(b=>b.questions.map(q=>[`${b.packageId}::${q.questionId}`,{b,q}]))));const current=computed(()=>{let r=s.orderedQuestionRefs[s.currentQuestionIndex];return r&&lookup.value.get(`${r.packageId}::${r.questionId}`)});const unavailable=computed(()=>s.orderedQuestionRefs.filter(r=>!lookup.value.has(`${r.packageId}::${r.questionId}`)));function start(n){Object.assign(s,{orderedQuestionRefs:createMistakeRound(n),currentQuestionIndex:0,answers:{},sessionStatus:'inProgress'});setup.value=false;saveMistakeSession(s)}function resume(){Object.assign(s,loadMistakeSession());setup.value=false}function objective(v){if(answered.value)return;selected.value=v;answered.value=true;let correct=v===current.value.q.correctAnswer;s.answers[`${current.value.b.packageId}::${current.value.q.questionId}`]={correct};recordMistake({packageId:current.value.b.packageId,questionId:current.value.q.questionId,questionType:current.value.q.questionType,result:correct});saveMistakeSession(s)}function free(e){s.answers[`${current.value.b.packageId}::${current.value.q.questionId}`]={status:e.rating};recordMistake({packageId:current.value.b.packageId,questionId:current.value.q.questionId,questionType:'freeText',result:e.rating});saveMistakeSession(s)}function next(){if(s.currentQuestionIndex<s.orderedQuestionRefs.length-1)s.currentQuestionIndex++;selected.value=null;answered.value=false;saveMistakeSession(s)}function finish(){s.sessionStatus='completed';saveMistakeSession(s)}const saved=loadMistakeSession()
</script><template><section class="package-mode-layout"><section v-if="setup" class="result-card"><p class="eyebrow">Fehlertraining</p><h2>{{summary.total?'Offene Fehler: '+summary.total:'Aktuell keine offenen Fehler.'}}</h2><p>MC {{summary.mc}} · Ja/Nein {{summary.yesNo}} · Freitext {{summary.freeText}} · Pakete: {{[...summary.packages].join(', ')||'–'}}</p><div v-if="summary.total" class="result-actions"><button v-if="saved?.orderedQuestionRefs?.length" class="primary-button" @click="resume">Letztes Fehlertraining fortsetzen</button><button class="primary-button" @click="start(10)">Schnellrunde</button><button class="secondary-button" @click="start(20)">Normale Runde</button><button class="secondary-button" @click="start('all')">Alle offenen Fehler</button></div></section><section v-else-if="current" class="quiz-layout"><aside class="score-card progress-card"><h2>Fehlertraining</h2><p>Frage {{s.currentQuestionIndex+1}} von {{s.orderedQuestionRefs.length}}</p></aside><QuizCard v-if="current.q.questionType==='mc'" :question="{...current.q,category:current.b.packageTitle}" :selected-answer="selected" :is-answered="answered" :is-last-question="s.currentQuestionIndex===s.orderedQuestionRefs.length-1" @select-answer="objective" @next-question="next" @restart-quiz="finish"/><YesNoCard v-else-if="current.q.questionType==='yesNo'" :question="current.q" :selected-answer="selected" :is-answered="answered" :is-last-question="s.currentQuestionIndex===s.orderedQuestionRefs.length-1" @select-answer="objective" @next-question="next" @finish="finish"/><FreeTextCard v-else :question="{...current.q,category:current.b.packageTitle}" :is-last-question="s.currentQuestionIndex===s.orderedQuestionRefs.length-1" :show-model-answer-toggle="true" @evaluated="free" @next-question="next" @restart-training="finish"/></section><section v-else class="result-card"><h2>Fehlertraining abgeschlossen</h2><p>Weiter offene Fehler: {{openMistakes().length}}</p><p v-if="unavailable.length">{{unavailable.length}} Fehlerfragen sind ohne geladene Paketbank derzeit nicht verfügbar.</p></section></section></template>